package local.proskurnin.remote;
import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Small bounded HTTP/1.1 server: one request per connection, LAN-only and strict Origin. */
final class RemoteHttp implements AutoCloseable {
 final RemoteService service;final Inet4Address address;final int prefix;final String authority;final boolean tls;final String originBase;final String cookieName;final ServerSocket listener;final Set<Socket> clients=Collections.synchronizedSet(new HashSet<>());volatile boolean live=true;
 final ThreadPoolExecutor pool=new ThreadPoolExecutor(2,2,0,TimeUnit.SECONDS,new ArrayBlockingQueue<Runnable>(4));
 RemoteHttp(RemoteService s,Inet4Address address,int prefix,boolean tls)throws Exception{service=s;this.address=address;this.prefix=prefix;this.tls=tls;cookieName=tls?"__Secure-tvremote":"tvremote";authority=address.getHostAddress()+(tls?":8766":":8765");originBase=(tls?"https://":"http://")+authority;listener=tls?RemoteTls.server(s):new ServerSocket();listener.setReuseAddress(true);listener.bind(new InetSocketAddress(address,tls?8766:8765),8);new Thread(()->accept(),"phone-remote-listen").start();}
 static boolean privateV4(byte[] a){return a.length==4&&((a[0]&255)==10||((a[0]&255)==172&&(a[1]&255)>=16&&(a[1]&255)<=31)||((a[0]&255)==192&&(a[1]&255)==168));}
 boolean local(InetAddress peer){byte[] a=address.getAddress(),b=peer.getAddress();if(!privateV4(b))return false;for(int i=0;i<prefix;i++)if(((a[i/8]^b[i/8])&(128>>(i%8)))!=0)return false;return true;}
 void accept(){while(live)try{Socket socket=listener.accept();if(!local(socket.getInetAddress())){socket.close();continue;}socket.setSoTimeout(3000);clients.add(socket);try{pool.execute(()->serve(socket));}catch(RejectedExecutionException e){clients.remove(socket);socket.close();}}catch(IOException e){if(live)android.util.Log.w("ProskurninRemote","Listener unavailable");}}
 static String line(InputStream in,int limit)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();int c;boolean cr=false;while((c=in.read())!=-1){if(c=='\n'){if(!cr)throw new IOException();byte[] bytes=b.toByteArray();return new String(bytes,0,bytes.length-1,"US-ASCII");}if(c<32&&c!='\r'||c>126||b.size()>=limit)throw new IOException();b.write(c);cr=c=='\r';}throw new EOFException();}
 void serve(Socket socket){try{InputStream in=socket.getInputStream();OutputStream out=socket.getOutputStream();String[] request=line(in,1024).split(" ");if(request.length!=3||!request[2].equals("HTTP/1.1"))throw new IOException();String method=request[0],path=request[1];HashMap<String,String> headers=new HashMap<>();int total=0;
  for(int i=0;;i++){String h=line(in,2048);if(h.isEmpty())break;total+=h.length();if(i>=32||total>8192)throw new IOException();int colon=h.indexOf(':');if(colon<1)throw new IOException();String k=h.substring(0,colon).toLowerCase(Locale.US),v=h.substring(colon+1).trim();if(headers.put(k,v)!=null)throw new IOException();}
  int length=Integer.parseInt(headers.getOrDefault("content-length","0"));if(length<0||length>(tls&&path.equals("/api/voice")?1010000:4096)||headers.containsKey("transfer-encoding")||(method.equals("POST")&&length<2)||(!method.equals("POST")&&length!=0))throw new IOException();byte[] raw=new byte[length];int off=0,read;while(off<length&&(read=in.read(raw,off,length-off))>0)off+=read;if(off!=length)throw new IOException();
  if(!authority.equals(headers.get("host"))||headers.containsKey("transfer-encoding")){reply(out,403,new JSONObject().put("error","host_denied"),null);return;}
  String origin=headers.get("origin");if(origin!=null&&!origin.equals(originBase)){reply(out,403,new JSONObject().put("error","origin_denied"),null);return;}
  if(!method.equals("GET")&&!method.equals("POST")){reply(out,405,new JSONObject().put("error","method"),null);return;}
  if(method.equals("GET")&&(path.equals("/")||path.equals("/app.js")||path.equals("/style.css"))){String file=path.equals("/")?"index.html":path.substring(1);byte[] data;try(InputStream asset=service.getAssets().open(file);ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] chunk=new byte[4096];int n;while((n=asset.read(chunk))!=-1)bytes.write(chunk,0,n);data=bytes.toByteArray();}send(out,200,file.endsWith("html")?"text/html; charset=utf-8":file.endsWith("js")?"text/javascript; charset=utf-8":"text/css; charset=utf-8",data,null);return;}
  if(method.equals("GET")&&(path.equals("/remote-ca.mobileconfig")||path.equals("/ca.cer"))){String name=path.substring(1);send(out,200,path.endsWith("mobileconfig")?"application/x-apple-aspen-config":"application/pkix-cert",RemoteTls.read(new File(service.getFilesDir(),name),16384),null);return;}
  if(!tls&&(path.equals("/api/text")||path.equals("/api/voice")||path.equals("/api/assistant"))){reply(out,403,new JSONObject().put("error","https_required"),null);return;}
  JSONObject body=new JSONObject();if(method.equals("POST")){if(!(originBase).equals(origin)||!"1".equals(headers.get("x-tv-request"))||!headers.getOrDefault("content-type","").startsWith("application/json")){reply(out,403,new JSONObject().put("error","origin_required"),null);return;}body=new JSONObject(new String(raw,"UTF-8"));}
  if(method.equals("POST")&&path.equals("/api/pair")){try{reply(out,200,service.auth.pair(body.getString("code"),body.optString("name","Телефон"),socket.getInetAddress().getHostAddress()),null);}catch(SecurityException e){reply(out,403,new JSONObject().put("error",e.getMessage()),null);}return;}
  if(method.equals("POST")&&path.equals("/api/pair/status")){try{String token=service.auth.poll(body.getString("pending"),socket.getInetAddress().getHostAddress());reply(out,200,new JSONObject().put("approved",token!=null),token==null?null:cookieName+"="+token+(tls?"; Secure":"")+"; HttpOnly; SameSite=Strict; Path=/api; Max-Age=2592000");}catch(SecurityException e){reply(out,403,new JSONObject().put("error",e.getMessage()),null);}return;}
  String token=null;for(String cookie:headers.getOrDefault("cookie","").split(";")){String value=cookie.trim();if(value.startsWith(cookieName+"="))token=value.substring(cookieName.length()+1);}String session=service.auth.authenticate(token);if(session==null){reply(out,401,new JSONObject().put("error","pair_required"),null);return;}
  if(method.equals("GET")&&path.equals("/api/state")){JSONObject state=RemoteActions.state(service);if(!tls)state.remove("field");state.put("secure",tls);reply(out,200,state,null);return;}
  if(method.equals("GET")&&path.equals("/api/field")){reply(out,tls?200:403,tls?new JSONObject().put("field",TextInputService.state()):new JSONObject().put("error","https_required"),null);return;}
  if(method.equals("POST")&&path.equals("/api/logout")){service.auth.revoke(session);reply(out,200,new JSONObject().put("ok",true),cookieName+"=; "+(tls?"Secure; ":"")+"HttpOnly; SameSite=Strict; Path=/api; Max-Age=0");return;}
  if(method.equals("POST")&&path.equals("/api/command")){if(!live||!service.getSharedPreferences("remote",0).getBoolean("enabled",false)){reply(out,503,new JSONObject().put("error","server_stopped"),null);return;}if(!service.auth.permit(session)){reply(out,429,new JSONObject().put("error","too_fast"),null);return;}boolean ok=RemoteActions.command(service,body);reply(out,ok?200:503,new JSONObject().put("ok",ok).put("error",ok?"":"control_unavailable"),null);return;}
  if(method.equals("POST")&&path.equals("/api/text")){if(!live||!service.getSharedPreferences("remote",0).getBoolean("enabled",false)){reply(out,503,new JSONObject().put("error","server_stopped"),null);return;}if(!service.auth.permit(session)){reply(out,429,new JSONObject().put("error","too_fast"),null);return;}boolean ok=TextInputService.set(body.getString("id"),body.getInt("revision"),body.getString("text"));reply(out,ok?200:409,new JSONObject().put("ok",ok).put("field",TextInputService.state()).put("error",ok?"":"field_changed"),null);return;}
  if(method.equals("POST")&&(path.equals("/api/voice")||path.equals("/api/assistant"))){if(!live||!service.getSharedPreferences("remote",0).getBoolean("enabled",false)){reply(out,503,new JSONObject().put("error","server_stopped"),null);return;}if(!service.auth.permit(session)){reply(out,429,new JSONObject().put("error","too_fast"),null);return;}try{if(path.equals("/api/voice"))reply(out,200,PhoneVoice.transcribe(service,body),null);else{boolean ok=PhoneVoice.send(service,body);reply(out,ok?200:400,new JSONObject().put("ok",ok),null);}}catch(Exception e){reply(out,503,new JSONObject().put("error","transcription_unavailable"),null);}return;}
  reply(out,404,new JSONObject().put("error","not_found"),null);
 }catch(Exception ignored){try{reply(socket.getOutputStream(),400,new JSONObject().put("error","invalid_request"),null);}catch(Exception suppressed){}}finally{clients.remove(socket);try{socket.close();}catch(Exception ignored){}}}
 void reply(OutputStream out,int status,JSONObject body,String cookie)throws Exception{send(out,status,"application/json; charset=utf-8",body.toString().getBytes("UTF-8"),cookie);}
 void send(OutputStream out,int status,String type,byte[] body,String cookie)throws Exception{String headers="HTTP/1.1 "+status+" "+(status==200?"OK":"Error")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+body.length+"\r\nCache-Control: no-store\r\nConnection: close\r\nX-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\nX-Frame-Options: DENY\r\nContent-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'\r\n"+(cookie==null?"":"Set-Cookie: "+cookie+"\r\n")+"\r\n";out.write(headers.getBytes("US-ASCII"));out.write(body);out.flush();}
 public void close(){live=false;try{listener.close();}catch(Exception ignored){}synchronized(clients){for(Socket socket:clients)try{socket.close();}catch(Exception ignored){}clients.clear();}pool.shutdownNow();}
}
